    # cell toward the open (right-hand) side of their lattice compartment.
    h=len(g); w=len(g[0]); out=[r[:] for r in g]
    # special generic packing: translate isolated foreground components right
    seen=set()
    for i in range(h):
      for j in range(w):
       if g[i][j]!=1 or (i,j) in seen: continue
       st=[(i,j)]; seen.add((i,j)); comp=[]
       while st:
        x,y=st.pop(); comp.append((x,y))
        for dx,dy in ((1,0),(-1,0),(0,1),(0,-1)):
         a,b=x+dx,y+dy
         if 0<=a<h and 0<=b<w and g[a][b]==1 and (a,b) not in seen:
