       # only move if the destination is empty and does not hit a marker
       if len(comp)<=3:
        if all(y+1<w and g[x][y+1]==0 for x,y in comp):
         for x,y in comp: out[x][y]=0
         for x,y in comp: out[x][y+1]=1
    return out"}

